function lazy2(fn) {
  let value;
  let loaded = false;
  const result = () => {
    if (loaded)
      return value;
    try {
      value = fn();
      loaded = true;
      return value;
    } catch (e) {
      throw e;
    }
  };
  result.reset = () => {
    loaded = false;
    value = undefined;
  };
  return result;
}

