    LSPServer.Clangd = {
      id: "clangd",
      root: NearestRoot(["compile_commands.json", "compile_flags.txt", ".clangd", "CMakeLists.txt", "Makefile"]),
      extensions: [".c", ".cpp", ".cc", ".cxx", ".c++", ".h", ".hpp", ".hh", ".hxx", ".h++"],
      async spawn(root) {
        const args2 = ["--background-index", "--clang-tidy"];
        const fromPath = which("clangd");
        if (fromPath) {
          return {
            process: spawn(fromPath, args2, {
              cwd: root
            })
          };
        }
        const ext2 = process.platform === "win32" ? ".exe" : "";
        const direct = path12.join(Global.Path.bin, "clangd" + ext2);
        if (await Filesystem.exists(direct)) {
          return {
            process: spawn(direct, args2, {
              cwd: root
            })
          };
        }
        const entries = await fs6.readdir(Global.Path.bin, { withFileTypes: true }).catch(() => []);
        for (const entry of entries) {
          if (!entry.isDirectory())
            continue;
          if (!entry.name.startsWith("clangd_"))
            continue;
          const candidate = path12.join(Global.Path.bin, entry.name, "bin", "clangd" + ext2);
          if (await Filesystem.exists(candidate)) {
            return {
              process: spawn(candidate, args2, {
                cwd: root
              })
            };
          }
        }
        if (Flag.OPENCODE_DISABLE_LSP_DOWNLOAD)
          return;
        log2.info("downloading clangd from GitHub releases");
        const releaseResponse = await fetch("https://api.github.com/repos/clangd/clangd/releases/latest");
        if (!releaseResponse.ok) {
          log2.error("Failed to fetch clangd release info");
          return;
        }
        const release = await releaseResponse.json();
        const tag = release.tag_name;
        if (!tag) {
          log2.error("clangd release did not include a tag name");
          return;
        }
        const platform = process.platform;
        const tokens = {
          darwin: "mac",
          linux: "linux",
          win32: "windows"
        };
        const token = tokens[platform];
        if (!token) {
          log2.error(`Platform ${platform} is not supported by clangd auto-download`);
          return;
        }
        const assets = release.assets ?? [];
        const valid = (item) => {
          if (!item.name)
            return false;
          if (!item.browser_download_url)
            return false;
          if (!item.name.includes(token))
            return false;
          return item.name.includes(tag);
        };
        const asset = assets.find((item) => valid(item) && item.name?.endsWith(".zip")) ?? assets.find((item) => valid(item) && item.name?.endsWith(".tar.xz")) ?? assets.find((item) => valid(item));
        if (!asset?.name || !asset.browser_download_url) {
          log2.error("clangd could not match release asset", { tag, platform });
          return;
        }
        const name3 = asset.name;
        const downloadResponse = await fetch(asset.browser_download_url);
        if (!downloadResponse.ok) {
          log2.error("Failed to download clangd");
          return;
        }
        const archive = path12.join(Global.Path.bin, name3);
        const buf = await downloadResponse.arrayBuffer();
        if (buf.byteLength === 0) {
          log2.error("Failed to write clangd archive");
          return;
        }
        await Filesystem.write(archive, Buffer.from(buf));
        const zip = name3.endsWith(".zip");
        const tar = name3.endsWith(".tar.xz");
        if (!zip && !tar) {
          log2.error("clangd encountered unsupported asset", { asset: name3 });
          return;
        }
        if (zip) {
          const ok = await Archive.extractZip(archive, Global.Path.bin).then(() => true).catch((error45) => {
            log2.error("Failed to extract clangd archive", { error: error45 });
            return false;
          });
          if (!ok)
            return;
        }
        if (tar) {
          await $4`tar -xf ${archive}`.cwd(Global.Path.bin).quiet().nothrow();
        }
        await fs6.rm(archive, { force: true });
        const bin = path12.join(Global.Path.bin, "clangd_" + tag, "bin", "clangd" + ext2);
        if (!await Filesystem.exists(bin)) {
          log2.error("Failed to extract clangd binary");
          return;
        }
        if (platform !== "win32") {
          await $4`chmod +x ${bin}`.quiet().nothrow();
        }
        await fs6.unlink(path12.join(Global.Path.bin, "clangd")).catch(() => {});
        await fs6.symlink(bin, path12.join(Global.Path.bin, "clangd")).catch(() => {});
        log2.info(`installed clangd`, { bin });
        return {
          process: spawn(bin, args2, {
            cwd: root
          })
        };
      }
    };
