function resolveClaxedoMcpCommand() {
  const execDir = path52.dirname(process.execPath);
  try {
    const entries = fs25.readdirSync(execDir);
    for (const entry of entries) {
      if (entry === "claxedo-mcp" || entry.startsWith("claxedo-mcp-")) {
        const candidate = path52.join(execDir, entry);
        try {
          fs25.accessSync(candidate, fs25.constants.X_OK);
          log11.info("Resolved claxedo-mcp from sidecar directory", { path: candidate });
          return [candidate];
        } catch {}
      }
    }
  } catch {}
  try {
    const sourcePath = new URL("../mcp/claxedo-mcp.ts", import.meta.url).pathname;
    if (fs25.existsSync(sourcePath)) {
      return ["bun", sourcePath];
    }
  } catch {}
  log11.warn("Could not resolve claxedo-mcp binary or source file");
  return [];
}
