async function writeIfChanged(filePath, content, mode2, force) {
  const tempPath = `${filePath}.tmp.${Date.now()}-${Math.random().toString(36).slice(2)}`;
  try {
    if (!force && fs25.existsSync(filePath)) {
      try {
        const existing = await fs25.promises.readFile(filePath, "utf-8");
        if (existing === content)
          return false;
      } catch {}
    }
    await fs25.promises.writeFile(tempPath, content, { mode: mode2 });
    try {
      await fs25.promises.rename(tempPath, filePath);
    } catch (renameError) {
      await fs25.promises.copyFile(tempPath, filePath);
      await fs25.promises.unlink(tempPath);
      await fs25.promises.chmod(filePath, mode2);
    }
    return true;
  } catch (error47) {
    log11.error("Failed to write file", { filePath, error: error47 });
    try {
      if (fs25.existsSync(tempPath)) {
        await fs25.promises.unlink(tempPath);
      }
    } catch {}
    throw error47;
  }
}
