import { EOL as EOL11 } from "os";
import { basename as basename6 } from "path";
var AgentCommand2 = cmd({
  command: "agent <name>",
  describe: "show agent configuration details",
  builder: (yargs) => yargs.positional("name", {
    type: "string",
    demandOption: true,
    description: "Agent name"
  }).option("tool", {
    type: "string",
    description: "Tool id to execute"
  }).option("params", {
    type: "string",
    description: "Tool params as JSON or a JS object literal"
  }),
  async handler(args2) {
    await bootstrap(process.cwd(), async () => {
      const agentName = args2.name;
      const agent = await Agent.get(agentName);
      if (!agent) {
        process.stderr.write(`Agent ${agentName} not found, run '${basename6(process.execPath)} agent list' to get an agent list` + EOL11);
        process.exit(1);
      }
      const availableTools = await getAvailableTools(agent);
      const resolvedTools = await resolveTools(agent, availableTools);
      const toolID = args2.tool;
      if (toolID) {
        const tool3 = availableTools.find((item) => item.id === toolID);
        if (!tool3) {
          process.stderr.write(`Tool ${toolID} not found for agent ${agentName}` + EOL11);
          process.exit(1);
        }
        if (resolvedTools[toolID] === false) {
          process.stderr.write(`Tool ${toolID} is disabled for agent ${agentName}` + EOL11);
          process.exit(1);
        }
        const params = parseToolParams(args2.params);
        const ctx = await createToolContext(agent);
        const result = await tool3.execute(params, ctx);
        process.stdout.write(JSON.stringify({ tool: toolID, input: params, result }, null, 2) + EOL11);
        return;
      }
      const output = {
        ...agent,
        tools: resolvedTools
      };
      process.stdout.write(JSON.stringify(output, null, 2) + EOL11);
    });
  }
});
async function getAvailableTools(agent) {
  const model = agent.model ?? await Provider.defaultModel();
  return ToolRegistry.tools(model, agent);
}
async function resolveTools(agent, availableTools) {
  const disabled = PermissionNext.disabled(availableTools.map((tool3) => tool3.id), agent.permission);
  const resolved = {};
  for (const tool3 of availableTools) {
    resolved[tool3.id] = !disabled.has(tool3.id);
  }
  return resolved;
}
function parseToolParams(input) {
  if (!input)
    return {};
  const trimmed = input.trim();
  if (trimmed.length === 0)
    return {};
  const parsed = iife(() => {
    try {
      return JSON.parse(trimmed);
    } catch (jsonError) {
      try {
        return new Function(`return (${trimmed})`)();
      } catch (evalError) {
        throw new Error(`Failed to parse --params. Use JSON or a JS object literal. JSON error: ${jsonError}. Eval error: ${evalError}.`);
      }
    }
  });
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("Tool params must be an object.");
  }
  return parsed;
}
async function createToolContext(agent) {
  const session = await Session.create({ title: `Debug tool run (${agent.name})` });
  const messageID = Identifier.ascending("message");
  const model = agent.model ?? await Provider.defaultModel();
  const now3 = Date.now();
  const message = {
    id: messageID,
    sessionID: session.id,
    role: "assistant",
    time: {
      created: now3
    },
    parentID: messageID,
    modelID: model.modelID,
    providerID: model.providerID,
    mode: "debug",
    agent: agent.name,
    path: {
      cwd: Instance.directory,
      root: Instance.worktree
    },
    cost: 0,
    tokens: {
      input: 0,
      output: 0,
      reasoning: 0,
      cache: {
        read: 0,
        write: 0
      }
    }
  };
  await Session.updateMessage(message);
  const ruleset = PermissionNext.merge(agent.permission, session.permission ?? []);
  return {
    sessionID: session.id,
    messageID,
    callID: Identifier.ascending("part"),
    agent: agent.name,
    abort: new AbortController().signal,
    messages: [],
    metadata: () => {},
    async ask(req) {
      for (const pattern of req.patterns) {
        const rule = PermissionNext.evaluate(req.permission, pattern, ruleset);
        if (rule.action === "deny") {
          throw new PermissionNext.DeniedError(ruleset);
        }
      }
    }
  };
}

