function formatTranscript(session, messages, options3) {
  let transcript = `# ${session.title}

`;
  transcript += `**Session ID:** ${session.id}
`;
  transcript += `**Created:** ${new Date(session.time.created).toLocaleString()}
`;
  transcript += `**Updated:** ${new Date(session.time.updated).toLocaleString()}

`;
  transcript += `---

`;
  for (const msg of messages) {
    transcript += formatMessage(msg.info, msg.parts, options3);
    transcript += `---

`;
  }
  return transcript;
}
function formatMessage(msg, parts2, options3) {
  let result = "";
  if (msg.role === "user") {
    result += `## User

`;
  } else {
    result += formatAssistantHeader(msg, options3.assistantMetadata);
  }
  for (const part of parts2) {
    result += formatPart(part, options3);
  }
  return result;
}
function formatAssistantHeader(msg, includeMetadata) {
  if (!includeMetadata) {
    return `## Assistant

`;
  }
  const duration3 = msg.time.completed && msg.time.created ? ((msg.time.completed - msg.time.created) / 1000).toFixed(1) + "s" : "";
  return `## Assistant (${Locale.titlecase(msg.agent)} \xB7 ${msg.modelID}${duration3 ? ` \xB7 ${duration3}` : ""})

`;
}
function formatPart(part, options3) {
  if (part.type === "text" && !part.synthetic) {
    return `${part.text}

`;
  }
  if (part.type === "reasoning") {
    if (options3.thinking) {
      return `_Thinking:_

${part.text}

`;
    }
    return "";
  }
  if (part.type === "tool") {
    let result = `**Tool: ${part.tool}**
`;
    if (options3.toolDetails && part.state.input) {
      result += `
**Input:**
\`\`\`json
${JSON.stringify(part.state.input, null, 2)}
\`\`\`
`;
    }
    if (options3.toolDetails && part.state.status === "completed" && part.state.output) {
      result += `
**Output:**
\`\`\`
${part.state.output}
\`\`\`
`;
    }
    if (options3.toolDetails && part.state.status === "error" && part.state.error) {
      result += `
**Error:**
\`\`\`
${part.state.error}
\`\`\`
`;
    }
    result += `
`;
    return result;
  }
  return "";
}

